2	import type { BlogPost } from "@prisma/client";
3	
4	export const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";
5	
6	/* ----------------------------------------------------------------------------
7	 * Fetch helpers
8	 * ------------------------------------------------------------------------- */
9	
10	/** Published posts, newest first — for the public blog index. */
11	export function getPublishedPosts(): Promise<BlogPost[]> {
12	  return db.blogPost.findMany({
13	    where: { published: true },
14	    orderBy: [{ publishedAt: "desc" }, { createdAt: "desc" }],
15	  });
16	}
17	
18	/** A single published post by slug, or null (drives notFound() on the page). */
19	export function getPublishedPost(slug: string): Promise<BlogPost | null> {
20	  return db.blogPost.findFirst({ where: { slug, published: true } });
21	}
22	
23	/** Every post regardless of status, newest edit first — for the admin editor. */
24	export function getAllPosts(): Promise<BlogPost[]> {
25	  return db.blogPost.findMany({ orderBy: { updatedAt: "desc" } });
26	}
27	
28	/** Look up any post by id (admin edit form). */
29	export function getPostById(id: string): Promise<BlogPost | null> {
30	  return db.blogPost.findUnique({ where: { id } });
31	}
32	
33	/* ----------------------------------------------------------------------------
34	 * Formatting
35	 * ------------------------------------------------------------------------- */
36	
37	export function formatDate(d: Date | string | null | undefined): string {
38	  if (!d) return "";
39	  const date = typeof d === "string" ? new Date(d) : d;
40	  return date.toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" });
41	}
42	
43	/** Rough read-time estimate from the raw markdown body. */
44	export function readMinutes(body: string): number {
45	  const words = body.trim().split(/\s+/).filter(Boolean).length;
46	  return Math.max(1, Math.round(words / 200));
47	}
48	
49	/* ----------------------------------------------------------------------------
50	 * Tiny, self-contained markdown → HTML renderer.
51	 *
52	 * No external dependency. Handles: # / ## / ### headings, **bold**, `code`,
53	 * fenced ``` code blocks, - / * and 1. lists, [links](url), and blank-line
54	 * separated paragraphs. HTML is escaped BEFORE any markdown is applied, and
55	 * inline code spans are protected so their contents are never re-processed.
56	 * Output carries Tailwind classes so it reads well on the dark theme (there is
57	 * no typography plugin installed).
58	 * ------------------------------------------------------------------------- */
59	
60	function esc(s: string): string {
61	  return s
62	    .replace(/&/g, "&amp;")
63	    .replace(/</g, "&lt;")
64	    .replace(/>/g, "&gt;");
65	}
66	
67	const CLS = {
68	  h1: "mt-10 mb-4 text-3xl font-bold tracking-tight text-white",
69	  h2: "mt-10 mb-3 text-2xl font-bold tracking-tight text-white",
70	  h3: "mt-8 mb-2 text-xl font-semibold text-white",
71	  p: "mb-4 leading-relaxed text-slate-300",
72	  ul: "mb-5 list-disc space-y-1.5 pl-6 text-slate-300 marker:text-brand-400",
73	  ol: "mb-5 list-decimal space-y-1.5 pl-6 text-slate-300 marker:text-brand-400",
74	  li: "leading-relaxed",
75	  a: "text-brand-300 underline decoration-brand-300/40 underline-offset-2 hover:text-brand-200",
76	  code: "rounded-md border border-white/10 bg-white/[0.06] px-1.5 py-0.5 font-mono text-[0.85em] text-brand-200",
77	  pre: "mb-5 overflow-x-auto rounded-xl border border-white/10 bg-navy-950/80 p-4 font-mono text-[13px] leading-relaxed text-slate-200",
78	};
79	
80	// Private-use sentinels wrap protected inline-code indices so they can never
81	// collide with ordinary digits in prose (e.g. "2 GB", "port 25565").
82	const S0 = "";
83	const S1 = "";
84	
85	/** Inline markdown for a single run of text. */
86	function inline(text: string): string {
87	  const codes: string[] = [];
88	  // Protect inline code first.
89	  let s = esc(text).replace(/`([^`]+)`/g, (_m, c: string) => {
90	    codes.push(c);
91	    return `${S0}${codes.length - 1}${S1}`;
92	  });
93	  // Bold.
94	  s = s.replace(/\*\*([^*]+)\*\*/g, '<strong class="font-semibold text-white">$1</strong>');
95	  // Links [text](url) — only http(s), root-relative, or anchors are allowed.
96	  s = s.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (_m, t: string, u: string) => {
97	    const safe = /^(https?:\/\/|\/|#)/.test(u) ? u : "#";
98	    const ext = safe.startsWith("http");
99	    return `<a class="${CLS.a}" href="${safe}"${ext ? ' target="_blank" rel="noopener noreferrer"' : ""}>${t}</a>`;
100	  });
101	  // Restore inline code.
102	  s = s.replace(new RegExp(`${S0}(\\d+)${S1}`, "g"), (_m, i: string) => `<code class="${CLS.code}">${codes[+i]}</code>`);
103	  return s;
104	}
105	
106	export function renderMarkdown(md: string): string {
107	  const lines = (md ?? "").replace(/\r\n/g, "\n").split("\n");
108	  const out: string[] = [];
109	  let i = 0;
110	
111	  while (i < lines.length) {
112	    const line = lines[i];
113	
114	    // Blank line — skip.
115	    if (!line.trim()) { i++; continue; }
116	
117	    // Horizontal rule.
118	    if (/^---+$/.test(line.trim())) {
119	      out.push('<hr class="my-8 border-white/[0.08]" />');
120	      i++;
121	      continue;
122	    }
123	
124	    // Fenced code block.
125	    if (/^```/.test(line.trim())) {
126	      const buf: string[] = [];
127	      i++;
128	      while (i < lines.length && !/^```/.test(lines[i].trim())) { buf.push(lines[i]); i++; }
129	      i++; // closing fence
130	      out.push(`<pre class="${CLS.pre}"><code>${esc(buf.join("\n"))}</code></pre>`);
131	      continue;
132	    }
133	
134	    // Headings.
135	    if (/^###\s+/.test(line)) { out.push(`<h3 class="${CLS.h3}">${inline(line.replace(/^###\s+/, ""))}</h3>`); i++; continue; }
136	    if (/^##\s+/.test(line))  { out.push(`<h2 class="${CLS.h2}">${inline(line.replace(/^##\s+/, ""))}</h2>`);  i++; continue; }
137	    if (/^#\s+/.test(line))   { out.push(`<h1 class="${CLS.h1}">${inline(line.replace(/^#\s+/, ""))}</h1>`);   i++; continue; }
138	
139	    // Ordered list.
140	    if (/^\s*\d+\.\s+/.test(line)) {
141	      const items: string[] = [];
142	      while (i < lines.length && /^\s*\d+\.\s+/.test(lines[i])) {
143	        items.push(lines[i].replace(/^\s*\d+\.\s+/, ""));
144	        i++;
145	      }
146	      out.push(`<ol class="${CLS.ol}">${items.map((t) => `<li class="${CLS.li}">${inline(t)}</li>`).join("")}</ol>`);
147	      continue;
148	    }
149	
150	    // Unordered list.
151	    if (/^\s*[-*]\s+/.test(line)) {
152	      const items: string[] = [];
153	      while (i < lines.length && /^\s*[-*]\s+/.test(lines[i])) {
154	        items.push(lines[i].replace(/^\s*[-*]\s+/, ""));
155	        i++;
156	      }
157	      out.push(`<ul class="${CLS.ul}">${items.map((t) => `<li class="${CLS.li}">${inline(t)}</li>`).join("")}</ul>`);
158	      continue;
159	    }
160	
161	    // Paragraph — gather until a blank line or block boundary.
162	    const para = [line];
163	    i++;
164	    while (
165	      i < lines.length &&
166	      lines[i].trim() &&
167	      !/^#{1,3}\s/.test(lines[i]) &&
168	      !/^\s*[-*]\s+/.test(lines[i]) &&
169	      !/^\s*\d+\.\s+/.test(lines[i]) &&
170	      !/^```/.test(lines[i].trim()) &&
171	      !/^---+$/.test(lines[i].trim())
172	    ) {
173	      para.push(lines[i]);
174	      i++;
175	    }
176	    out.push(`<p class="${CLS.p}">${inline(para.join(" "))}</p>`);
177	  }
178	
179	  return out.join("\n");
180	}
